import{_ as t,c as s,o as r,j as i,Y as n,t as d}from"./chunks/framework.BNTND4LZ.js";const g=JSON.parse('{"title":"charmap | x-cmd man (man5) | character set description file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | charmap - character set description file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"charmap | x-cmd man (man5) | character set description file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | charmap - character set description file"}]]},"headers":[],"params":{"isMan":true,"man":"charmap","category":"man5","desc":"character set description file"},"relativePath":"man5/charmap.md","filePath":"man5/[man].md"}'),h={name:"man5/charmap.md"},o={class:"visually-hidden"};function c(a,e,l,m,p,f){return r(),s("div",null,[i("h1",o,d(a.$params.man),1),e[0]||(e[0]=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>charmap - character set description file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>A character set description (charmap) defines all available characters and their encodings in a character set. <strong>localedef</strong>(1) can use charmaps to create locale variants for different character sets.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h3><p>The charmap file starts with a header that may consist of the following keywords:</p><dl><dt>&lt;<em>code_set_name</em>&gt;</dt><dd>is followed by the name of the character map.</dd><dt>&lt;<em>comment_char</em>&gt;</dt><dd>is followed by a character that will be used as the comment character for the rest of the file. It defaults to the number sign (#).</dd><dt>&lt;<em>escape_char</em>&gt;</dt><dd>is followed by a character that should be used as the escape character for the rest of the file to mark characters that should be interpreted in a special way. It defaults to the backslash (\\).</dd><dt>&lt;<em>mb_cur_max</em>&gt;</dt><dd>is followed by the maximum number of bytes for a character. The default value is 1.</dd><dt>&lt;<em>mb_cur_min</em>&gt;</dt><dd>is followed by the minimum number of bytes for a character. This value must be less than or equal than &lt;<em>mb_cur_max</em>&gt;. If not specified, it defaults to &lt;<em>mb_cur_max</em>&gt;.</dd></dl><p>The character set definition section starts with the keyword <em>CHARMAP</em> in the first column.</p><p>The following lines may have one of the two following forms to define the character set:</p><dl><dt>&lt;<em>character</em>&gt; <em>byte-sequence comment</em></dt><dd>This form defines exactly one character and its byte sequence, <em>comment</em> being optional.</dd><dt>&lt;<em>character</em>&gt;..&lt;<em>character</em>&gt; <em>byte-sequence comment</em></dt><dd>This form defines a character range and its byte sequence, <em>comment</em> being optional.</dd></dl><p>The character set definition section ends with the string <em>END CHARMAP</em>.</p><p>The character set definition section may optionally be followed by a section to define widths of characters.</p><p>The <em>WIDTH_DEFAULT</em> keyword can be used to define the default width for all characters not explicitly listed. The default character width is 1.</p><p>The width section for individual characters starts with the keyword <em>WIDTH</em> in the first column.</p><p>The following lines may have one of the two following forms to define the widths of the characters:</p><dl><dt>&lt;<em>character</em>&gt; <em>width</em></dt><dd>This form defines the width of exactly one character.</dd><dt>&lt;<em>character</em>&gt;...&lt;<em>character</em>&gt; <em>width</em></dt><dd>This form defines the width for all the characters in the range.</dd></dl><p>The width definition section ends with the string <em>END WIDTH</em>.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/usr/share/i18n/charmaps</em></dt><dd>Usual default character map path.</dd></dl><h2 id="standards" tabindex="-1">STANDARDS <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;STANDARDS&quot;">​</a></h2><p>POSIX.2.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>The Euro sign is defined as follows in the <em>UTF-8</em> charmap:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">U20AC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /xe2/x82/xac EURO SIGN</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>iconv</strong>(1), <strong>locale</strong>(1), <strong>localedef</strong>(1), <strong>locale</strong>(5), <strong>charsets</strong>(7)</p>',26))])}const b=t(h,[["render",c]]);export{g as __pageData,b as default};
